void model_inference_processed(const float input_image[1][240][520][3], float ouput_array_cut[384]) 
{
  float output_array[1][384];

  clock_t start, end;
  float cpu_time_used;

  // Start time
  start = clock();

  model_inference(input_image, output_array);

  // End time
  end = clock();

  // Calculate the elapsed time
  cpu_time_used = ((float) (end - start)) / CLOCKS_PER_SEC;

  // print model ouput
  // printf("model output: \n");

  // loop array
  // for (int i = 0; i < 96; i++) {
  //   printf("%f ", output_array[0][i]);
  //   if ((i + 1) % 16 == 0) {
  //       printf("\n");  // Print new line after every 16th element
  //   }
  // }


  // Print speed
  //printf("Time taken by function: %f seconds\n", cpu_time_used);

    // Copy the first 64 elements from arr[0] to new_arr
  for (int i = 0; i < 384; i++) {
    ouput_array_cut[i] = output_array[0][i];
  }

return;
}